GlobalStyles {
	Rule 'div.fa-wrapper' {
		display = inline_block,
		margin_right = rem(0.3),

		Rule '&> svg' {
			margin_top = px(2),
			margin_bottom = px(-2),
			width = rem(1),
			height = rem(1),
		}
	}
}

return function(name)
	return div {
		class = 'fa-wrapper',
		Raw(icons[string.lower(name)]),
	}
end
